#!/usr/bin/env bash
set -Eeuo pipefail
umask 0022

PATCH_NAME='linxen_home_editorial_commerce_v2'
BACKUP_ROOT='storage/app/ai_patch_backups'
STAMP="$(date '+%Y%m%d_%H%M%S')"
BACKUP_DIR="${BACKUP_ROOT}/${PATCH_NAME}_${STAMP}"
MANIFEST="${BACKUP_DIR}/manifest.tsv"
PATCH_COMMITTED=0

test -f artisan || {
  printf '%s\n' 'ERROR: Không đứng tại Laravel root.' >&2
  exit 1
}

REQUIRED_FILES=(
  'app/Http/Controllers/CommerceV2/CatalogPageController.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/home.blade.php'
  'public/commerce-v2/themes/luxe-commerce-v1.css'
  'app/Console/Commands/CommerceV2LuxeCommerceThemeSmokeCommand.php'
  'app/Console/Commands/CommerceV2DefaultUiSmokeCommand.php'
  'app/Console/Commands/CommerceV2CheckoutFoundationSmokeCommand.php'
)

for FILE in "${REQUIRED_FILES[@]}"
do
  test -f "$FILE" || {
    printf 'ERROR: Thiếu source bắt buộc: %s\n' "$FILE" >&2
    exit 1
  }
done

grep -Fq 'data-lxcv1-page="home"' \
  resources/views/commerce_v2/themes/luxe_commerce_v1/pages/home.blade.php || {
    printf '%s\n' 'ERROR: Luxe Commerce home source đã drift.' >&2
    exit 1
  }

grep -Fq '.lxcv1-home-hero' \
  public/commerce-v2/themes/luxe-commerce-v1.css || {
    printf '%s\n' 'ERROR: Luxe Commerce CSS nền đã drift.' >&2
    exit 1
  }

grep -Fq '$this->client->listing(' \
  app/Http/Controllers/CommerceV2/CatalogPageController.php || {
    printf '%s\n' 'ERROR: CatalogPageController home listing đã drift.' >&2
    exit 1
  }

FILES=(
  'app/Http/Controllers/CommerceV2/CatalogPageController.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/home.blade.php'
  'public/commerce-v2/themes/luxe-commerce-v1.css'
  'app/Console/Commands/CommerceV2HomeEditorialExperienceSmokeCommand.php'
)

mkdir -p "$BACKUP_DIR"
: > "$MANIFEST"

for FILE in "${FILES[@]}"
do
  if [ -e "$FILE" ]; then
    mkdir -p "$BACKUP_DIR/$(dirname "$FILE")"
    cp -p "$FILE" "$BACKUP_DIR/$FILE"
    printf 'existing\t%s\n' "$FILE" >> "$MANIFEST"
  else
    printf 'new\t%s\n' "$FILE" >> "$MANIFEST"
  fi
done

rollback_patch() {
  STATUS="$?"

  if [ "$PATCH_COMMITTED" -eq 1 ]; then
    exit "$STATUS"
  fi

  if [ -f "$MANIFEST" ]; then
    while IFS=$'\t' read -r KIND FILE
    do
      if [ "$KIND" = 'existing' ]; then
        mkdir -p "$(dirname "$FILE")"
        cp -p "$BACKUP_DIR/$FILE" "$FILE"
      elif [ "$KIND" = 'new' ]; then
        rm -f "$FILE"
      fi
    done < "$MANIFEST"
  fi

  printf 'PATCH_ROLLBACK=PASS status=%s\n' "$STATUS" >&2
  exit "$STATUS"
}

trap rollback_patch ERR INT TERM

python3 <<'PY_PAYLOAD'
from pathlib import Path
import base64
import json
import os
import re

payload = json.loads(base64.b64decode('').decode('utf-8'))
css_module = base64.b64decode('').decode('utf-8')


def atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + '.ai_patch_tmp')
    tmp.write_text(content, encoding='utf-8')
    os.replace(tmp, path)

for relative, content in payload.items():
    atomic_write(Path(relative), content)

controller_path = Path(
    'app/Http/Controllers/CommerceV2/CatalogPageController.php'
)
controller = controller_path.read_text(encoding='utf-8')
marker = 'AI_PATCH_LINXEN_HOME_EDITORIAL_COMMERCE_V2'

if marker not in controller:
    needle = '$listing = $this->client->listing(8);'
    replacement = (
        '/* AI_PATCH_LINXEN_HOME_EDITORIAL_COMMERCE_V2 */\n'
        '            $listing = $this->client->listing(12);'
    )

    if needle not in controller:
        raise SystemExit('HOME_LISTING_ANCHOR_DRIFT')

    controller = controller.replace(needle, replacement, 1)
else:
    controller = controller.replace(
        '$this->client->listing(8)',
        '$this->client->listing(12)',
        1
    )

controller = controller.replace(
    "'pageTitle' => 'LIN XÉN — Váy thiết kế hiện đại',",
    "'pageTitle' => 'LIN XÉN — Váy thiết kế cho nhịp sống hiện đại',",
    1
)
controller = controller.replace(
    "'pageDescription' => 'Khám phá váy thiết kế LIN XÉN với màu sắc, kích thước, giá và tồn kho được cập nhật từ hệ thống chính thức.',",
    "'pageDescription' => 'Khám phá thiết kế LIN XÉN qua hình ảnh đã duyệt, màu sắc, kích thước, giá và tồn kho từ hệ thống chính thức.',",
    1
)
atomic_write(controller_path, controller)

css_path = Path('public/commerce-v2/themes/luxe-commerce-v1.css')
css = css_path.read_text(encoding='utf-8')
start = '/* AI_PATCH_LINXEN_HOME_EDITORIAL_COMMERCE_V2_CSS_START */'
end = '/* AI_PATCH_LINXEN_HOME_EDITORIAL_COMMERCE_V2_CSS_END */'
pattern = re.compile(
    re.escape(start) + r'.*?' + re.escape(end) + r'\n?',
    re.S
)
css = pattern.sub('', css).rstrip() + '\n\n' + css_module.strip() + '\n'
atomic_write(css_path, css)
PY_PAYLOAD

php -l \
  app/Http/Controllers/CommerceV2/CatalogPageController.php
php -l \
  app/Console/Commands/CommerceV2HomeEditorialExperienceSmokeCommand.php

grep -Fq 'data-lxcv1-home-experience="editorial-commerce-v2"' \
  resources/views/commerce_v2/themes/luxe_commerce_v1/pages/home.blade.php

grep -Fq 'data-lxh2-commercial-rail' \
  resources/views/commerce_v2/themes/luxe_commerce_v1/pages/home.blade.php

grep -Fq 'data-lxh2-editorial-story' \
  resources/views/commerce_v2/themes/luxe_commerce_v1/pages/home.blade.php

grep -Fq 'AI_PATCH_LINXEN_HOME_EDITORIAL_COMMERCE_V2_CSS_START' \
  public/commerce-v2/themes/luxe-commerce-v1.css

grep -Fq '$this->client->listing(12)' \
  app/Http/Controllers/CommerceV2/CatalogPageController.php

python3 <<'PY_CSS'
from pathlib import Path
css = Path(
    'public/commerce-v2/themes/luxe-commerce-v1.css'
).read_text(encoding='utf-8')

if css.count('{') != css.count('}'):
    raise SystemExit('LUXE_HOME_CSS_BRACE_MISMATCH')

print('LUXE_HOME_CSS_STATIC=PASS')
PY_CSS

env \
  CACHE_STORE=file \
  CACHE_DRIVER=file \
  SESSION_DRIVER=file \
  php artisan view:clear

env \
  CACHE_STORE=file \
  CACHE_DRIVER=file \
  SESSION_DRIVER=file \
  php artisan commerce-v2:home-editorial-experience-smoke

env \
  CACHE_STORE=file \
  CACHE_DRIVER=file \
  SESSION_DRIVER=file \
  php artisan commerce-v2:luxe-commerce-theme-smoke

env \
  CACHE_STORE=file \
  CACHE_DRIVER=file \
  SESSION_DRIVER=file \
  php artisan commerce-v2:default-ui-smoke

env \
  CACHE_STORE=file \
  CACHE_DRIVER=file \
  SESSION_DRIVER=file \
  php artisan commerce-v2:checkout-foundation-smoke

env \
  CACHE_STORE=file \
  CACHE_DRIVER=file \
  SESSION_DRIVER=file \
  php artisan commerce-v2:pdp-variant-matrix-smoke

PATCH_COMMITTED=1
trap - ERR INT TERM

if env \
  CACHE_STORE=file \
  CACHE_DRIVER=file \
  SESSION_DRIVER=file \
  php artisan optimize:clear
then
  printf '%s\n' 'LUXE_HOME_OPTIMIZE_CLEAR=PASS'
else
  printf '%s\n' 'LUXE_HOME_OPTIMIZE_CLEAR=WARNING_NO_ROLLBACK' >&2
fi

printf '%s\n' 'LINXEN_HOME_EDITORIAL_COMMERCE_V2_SOURCE_PATCH=PASS'
printf '%s\n' 'HOME_EXPERIENCE=EDITORIAL_COMMERCE_V2'
printf '%s\n' 'HERO_MEDIA=CANONICAL_APPROVED_PRODUCT_MEDIA'
printf '%s\n' 'COMMERCIAL_RAIL=TRUTH_BASED_NO_FAKE_COUNTDOWN'
printf '%s\n' 'COLLECTION_SOURCE=COMMERCE_V2_CANONICAL'
printf '%s\n' 'HOME_LISTING_LIMIT=12'
printf '%s\n' 'DEFAULT_SITE_THEME=luxe_commerce_v1'
printf '%s\n' 'DEFAULT_PDP_VARIANT=luxe_clarity_v1'
printf '%s\n' 'EXACT_SELLABLE_SKU=PRESERVED'
printf '%s\n' 'CART_CHECKOUT_ORDER=UNCHANGED'
printf '%s\n' 'MIGRATION=NONE'
printf '%s\n' 'DB_MUTATION=NONE'
printf '%s\n' 'ORDER_PROVIDER_META_MUTATION=NONE'
printf 'BACKUP_DIR=%s\n' "$BACKUP_DIR"
